package io.xeros.solo;
import io.xeros.*;import io.xeros.model.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.npc.actions.NPCHitPlayer;import io.xeros.content.combat.*;import io.xeros.content.combat.npc.*;import io.xeros.content.combat.magic.*;
public class Retaliation73Check{
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);}
 static Player actor(){Player p=MageArenaPlayableCheck.actor();p.setLoginName("ret73audit");p.autoRet=1;p.getItems().setEquipment(27275,1,3,false);p.getEquipmentChargeLedger().set("e3",1000);p.getMageArena().start();MageArenaPlayableCheck.apply(p);return p;}
 public static void main(String[]a)throws Exception{try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();Player p=actor();NPC n=MageArenaPlayableCheck.form(p);ok(SoloEquipmentCharges.ready(p),"Shadow charged");NPCHitPlayer.applyAutoAttackDamage(n,p,n.getNpcAutoAttacks().get(0));ok(p.npcAttackingIndex==n.getIndex(),"ON retaliates to Kolodion");ok(p.npcFollowingIndex==n.getIndex(),"Retaliation follows the current NPC");p.autoRet=0;p.attacking.reset();NPCHitPlayer.applyAutoAttackDamage(n,p,n.getNpcAutoAttacks().get(0));ok(p.npcAttackingIndex==0,"OFF leaves no attack target");p.autoRet=1;p.attackEntity(n);MageArenaPlayableCheck.kill(p,n);SkillsAuditCheck.tick(5);MageArenaPlayableCheck.apply(p);NPC next=MageArenaPlayableCheck.form(p);System.out.println("PHASE next="+next.getIndex()+" target="+p.npcAttackingIndex+" follow="+p.npcFollowingIndex);ok(next!=n,"Next form created");ok(p.npcAttackingIndex==next.getIndex(),"ON reacquires next Kolodion form");p.attacking.reset();p.clickNpcType=1;NPCHitPlayer.applyAutoAttackDamage(next,p,next.getNpcAutoAttacks().get(0));ok(p.clickNpcType==0&&p.npcFollowingIndex==next.getIndex(),"Retaliation clears stale NPC interaction");p.clickNpcType=0;p.getEquipmentChargeLedger().set("e3",0);ok(!SoloEquipmentCharges.ready(p),"Empty Shadow blocks attack despite ON");MageArenaPlayableCheck.clear(p);PlayerHandler.players[p.getIndex()]=p;p.setDisconnected(false);p.autoRet=1;p.attacking.reset();p.underAttackByNpc=0;p.getEquipmentChargeLedger().set("e3",1000);NPC guard=new NPC(3010,p.getPosition());ok(guard.getHealth().getMaximumHealth()>0,"Guard uses configured combat stats");guard.oldIndex=p.getIndex();NPCHitPlayer.applyDamage(guard,Server.npcHandler);ok(p.npcAttackingIndex==guard.getIndex()&&p.npcFollowingIndex==guard.getIndex(),"Legacy Guard ON selects and follows attacker");p.attacking.reset();p.autoRet=0;NPCHitPlayer.applyDamage(guard,Server.npcHandler);ok(p.npcAttackingIndex==0,"Legacy Guard OFF leaves no attack target");System.out.println("AUDIT_COMPLETE");System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}